import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`content-proposal-generator`,heroTitle:`Draft client proposals in minutes`,heroSubtitle:`Perplexity Computer researches your client, builds a custom proposal with pricing and terms, and drafts a send-ready email — automatically.`,inputUrlCta:`Draft my proposal`,inputUrlPlaceholder:`e.g. client URL`,inputUrlPrefill:`Go to {url} and research this client or use the provided description to draft a professional content proposal email. 1) Research the client's business, industry, and content needs based on their website or the description provided. 2) Write a professional proposal email that includes: a concise project summary describing the scope of work, a recommended package with specific deliverables, a detailed pricing breakdown with line items, a realistic timeline with milestones, clearly stated revision limits (e.g., 2 rounds per deliverable), and payment terms including deposit requirements, due dates, and accepted methods. 3) Structure the email so it functions as a lightweight agreement — the client can reply to accept and both parties have clear boundaries documented. 4) Include a polite but firm section on what happens if scope changes mid-project. 5) Deliver the final proposal email ready to copy and send, plus a summary table of all terms for your own records.`,heroOverlaySteps:[`Researching the client's business, industry, and content needs`,`Building your recommended package with pricing and deliverables`,`Drafting the proposal email with timeline, revisions, and payment terms`,`Professional proposal email with built-in agreement — ready to send`],generatingSteps:[`Visiting {url} to research the client's business and content needs`,`Designing an agent to structure packages, pricing, and project terms`,`Configuring proposal formatting with scope, timeline, and revision limits`,`Setting up the send-ready email with embedded agreement terms`],featureSectionTitle:`From client brief to send-ready proposal`,featureCardTitles:[`Connects to your business stack`,`Outputs you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Docs, Google Sheets, Notion — Computer plugs into your tools so proposals flow from drafting to sending to invoicing in one workflow.`,`Professional proposal emails. Pricing breakdowns with line items. Timeline and milestone tables. Revision limits and payment terms — baked right into the message.`],capabilitySectionTitle:`Your proposal writer, on autopilot`,capabilitySectionSubtitle:`Enter the client details, step away, come back to a send-ready proposal.`,capabilityCards:[{title:`Client Research`,description:`Computer can analyze a client's website, industry, and positioning — so your proposal speaks directly to their business and content needs.`},{title:`Package Building`,description:`Computer can recommend a service package with specific deliverables, pricing tiers, and line-item breakdowns tailored to the project scope.`},{title:`Terms & Boundaries`,description:`Computer can draft revision limits, payment terms, deposit requirements, and scope-change clauses — so you never start a project without clear boundaries.`},{title:`Connect Your Tools`,description:`Computer can send via Gmail, save to Google Docs, log pricing in Google Sheets, and track projects in Notion — build workflows across your entire client stack.`},{title:`Remember Your Rates`,description:`Computer can remember your standard packages, hourly rates, and preferred terms across sessions — so every new proposal stays consistent with your business.`},{title:`Follow-Up Alerts`,description:`Computer can track which proposals are pending and alert you when it's time to follow up — so no client slips through the cracks.`}]});export{t as default};
